arguments.cmd:
apply_patch <<'PATCH'
*** Begin Patch
*** Add File: output/assets/styles.css
+:root {
+  /*
+    RedRoom Fitness — dark, premium, immersive.
+    Palette uses OKLCH per web-design-expert skill.
+  */
+  --bg-0: oklch(12% 0.02 255);
+  --bg-1: oklch(16% 0.02 255);
+  --bg-2: oklch(20% 0.02 255);
+  --line: oklch(28% 0.02 255);
+
+  --text-0: oklch(96% 0.01 255);
+  --text-1: oklch(84% 0.02 255);
+  --text-2: oklch(72% 0.02 255);
+
+  --red: oklch(60% 0.25 25);
+  --red-2: oklch(52% 0.22 25);
+  --glow: oklch(70% 0.22 25);
+
+  --success: oklch(74% 0.16 145);
+  --danger: oklch(62% 0.23 25);
+
+  --shadow: 0 18px 60px rgba(0, 0, 0, 0.55);
+  --shadow-soft: 0 10px 28px rgba(0, 0, 0, 0.35);
+
+  /* Spacing scale (8px base) */
+  --space-1: 4px;
+  --space-2: 8px;
+  --space-3: 16px;
+  --space-4: 24px;
+  --space-5: 32px;
+  --space-6: 48px;
+  --space-7: 64px;
+  --space-8: 96px;
+
+  --radius-1: 12px;
+  --radius-2: 18px;
+  --radius-pill: 999px;
+
+  --container: 1200px;
+  --nav-h: 74px;
+
+  --easing: cubic-bezier(0.2, 0.8, 0.2, 1);
+  --dur-1: 140ms;
+  --dur-2: 220ms;
+  --dur-3: 520ms;
+}
+
+* { box-sizing: border-box; }
+
+html, body {
+  height: 100%;
+}
+
+body {
+  margin: 0;
+  color: var(--text-0);
+  background: radial-gradient(1200px 900px at 15% 0%, oklch(18% 0.05 25), transparent 55%),
+    radial-gradient(900px 700px at 90% 30%, oklch(22% 0.03 25), transparent 60%),
+    linear-gradient(180deg, var(--bg-0), var(--bg-1));
+  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
+  letter-spacing: 0.01em;
+  overflow-x: hidden;
+}
+
+img { max-width: 100%; display: block; }
+
+a { color: inherit; text-decoration: none; }
+
+a:focus-visible,
+button:focus-visible,
+input:focus-visible,
+select:focus-visible {
+  outline: 2px solid var(--glow);
+  outline-offset: 3px;
+}
+
+.container {
+  width: min(var(--container), 100% - 32px);
+  margin-inline: auto;
+}
+
+.sr-only {
+  position: absolute;
+  width: 1px;
+  height: 1px;
+  padding: 0;
+  margin: -1px;
+  overflow: hidden;
+  clip: rect(0, 0, 0, 0);
+  white-space: nowrap;
+  border: 0;
+}
+
+/* Top promo bar */
+.promo {
+  position: sticky;
+  top: 0;
+  z-index: 60;
+  background: linear-gradient(90deg, oklch(20% 0.06 25), oklch(16% 0.02 255));
+  border-bottom: 1px solid color-mix(in oklch, var(--line), transparent 40%);
+}
+
+.promo__inner {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: var(--space-3);
+  padding: 10px 0;
+  font-size: 14px;
+  color: var(--text-1);
+}
+
+.promo__cta {
+  display: inline-flex;
+  align-items: center;
+  gap: 10px;
+  padding: 8px 12px;
+  border-radius: var(--radius-pill);
+  background: color-mix(in oklch, var(--red), black 35%);
+  color: var(--text-0);
+  border: 1px solid color-mix(in oklch, var(--red), white 10%);
+  transition: transform var(--dur-1) var(--easing), filter var(--dur-1) var(--easing);
+}
+
+.promo__cta:hover { transform: translateY(-1px); filter: brightness(1.05); }
+
+/* Header / Nav */
+header.site-header {
+  position: sticky;
+  top: 41px;
+  z-index: 50;
+  background: color-mix(in oklch, var(--bg-0), transparent 8%);
+  backdrop-filter: blur(10px);
+  border-bottom: 1px solid color-mix(in oklch, var(--line), transparent 30%);
+}
+
+.nav {
+  height: var(--nav-h);
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: var(--space-3);
+}
+
+.brand {
+  display: inline-flex;
+  align-items: center;
+  gap: 12px;
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+}
+
+.brand__mark {
+  width: 36px;
+  height: 36px;
+  border-radius: 10px;
+  background: radial-gradient(circle at 30% 30%, var(--glow), var(--red) 55%, var(--red-2));
+  box-shadow: 0 10px 24px rgba(230, 57, 70, 0.25);
+}
+
+.brand__text {
+  display: grid;
+  line-height: 1;
+}
+
+.brand__text strong { font-size: 18px; }
+.brand__text span { font-size: 12px; color: var(--text-2); letter-spacing: 0.18em; }
+
+.nav__links {
+  display: flex;
+  align-items: center;
+  gap: 18px;
+  flex-wrap: wrap;
+}
+
+.nav__links a {
+  font-size: 13px;
+  text-transform: uppercase;
+  letter-spacing: 0.14em;
+  color: var(--text-1);
+  padding: 10px 10px;
+  border-radius: var(--radius-pill);
+  transition: background var(--dur-1) var(--easing), color var(--dur-1) var(--easing);
+}
+
+.nav__links a:hover {
+  color: var(--text-0);
+  background: color-mix(in oklch, var(--bg-2), transparent 30%);
+}
+
+.nav__links a[aria-current="page"] {
+  color: var(--text-0);
+  background: color-mix(in oklch, var(--red), black 65%);
+  border: 1px solid color-mix(in oklch, var(--red), white 12%);
+}
+
+.nav__actions {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+}
+
+.btn {
+  appearance: none;
+  border: 1px solid color-mix(in oklch, var(--line), transparent 25%);
+  background: color-mix(in oklch, var(--bg-2), transparent 18%);
+  color: var(--text-0);
+  padding: 12px 14px;
+  border-radius: var(--radius-pill);
+  cursor: pointer;
+  font-weight: 650;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+  font-size: 12px;
+  transition: transform var(--dur-1) var(--easing), background var(--dur-1) var(--easing), border-color var(--dur-1) var(--easing);
+}
+
+.btn:hover { transform: translateY(-1px); border-color: color-mix(in oklch, var(--red), white 10%); }
+
+.btn--primary {
+  background: linear-gradient(180deg, color-mix(in oklch, var(--red), white 6%), var(--red-2));
+  border-color: color-mix(in oklch, var(--red), white 12%);
+  box-shadow: 0 18px 40px rgba(230, 57, 70, 0.25);
+}
+
+.btn--primary:hover { filter: brightness(1.05); }
+
+.btn--ghost {
+  background: transparent;
+}
+
+.btn--lg {
+  padding: 16px 18px;
+  font-size: 13px;
+}
+
+.hamburger {
+  display: none;
+  width: 44px;
+  height: 44px;
+  border-radius: 12px;
+}
+
+.hamburger span {
+  display: block;
+  width: 18px;
+  height: 2px;
+  background: var(--text-0);
+  margin: 4px auto;
+  border-radius: 2px;
+}
+
+.mobile-drawer {
+  display: none;
+}
+
+/* Hero */
+.hero {
+  padding: calc(var(--space-7) + 10px) 0 var(--space-7);
+  position: relative;
+}
+
+.hero::before {
+  content: "";
+  position: absolute;
+  inset: 0;
+  background: radial-gradient(1200px 550px at 50% 15%, color-mix(in oklch, var(--red), transparent 65%), transparent 60%);
+  pointer-events: none;
+}
+
+.hero__grid {
+  display: grid;
+  grid-template-columns: 1.15fr 0.85fr;
+  gap: var(--space-7);
+  align-items: center;
+}
+
+.kicker {
+  display: inline-flex;
+  align-items: center;
+  gap: 10px;
+  padding: 10px 14px;
+  border-radius: var(--radius-pill);
+  border: 1px solid color-mix(in oklch, var(--line), transparent 35%);
+  background: color-mix(in oklch, var(--bg-2), transparent 25%);
+  color: var(--text-1);
+  font-size: 12px;
+  letter-spacing: 0.14em;
+  text-transform: uppercase;
+}
+
+.kicker__dot {
+  width: 10px;
+  height: 10px;
+  border-radius: 3px;
+  background: var(--red);
+  box-shadow: 0 0 0 4px color-mix(in oklch, var(--red), transparent 80%);
+}
+
+.hero h1 {
+  margin: var(--space-4) 0 var(--space-3);
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.06em;
+  font-size: clamp(36px, 4.2vw, 64px);
+  line-height: 0.95;
+}
+
+.hero p {
+  margin: 0 0 var(--space-5);
+  color: var(--text-1);
+  font-size: 16px;
+  line-height: 1.65;
+  max-width: 56ch;
+}
+
+.hero__actions {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 12px;
+  align-items: center;
+}
+
+.hero__stats {
+  margin-top: var(--space-6);
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: var(--space-3);
+}
+
+.stat {
+  padding: var(--space-3);
+  border-radius: var(--radius-1);
+  border: 1px solid color-mix(in oklch, var(--line), transparent 20%);
+  background: linear-gradient(180deg, color-mix(in oklch, var(--bg-2), transparent 18%), transparent);
+}
+
+.stat strong {
+  display: block;
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.12em;
+  font-size: 14px;
+}
+
+.stat span {
+  display: block;
+  margin-top: 6px;
+  color: var(--text-2);
+  font-size: 13px;
+  line-height: 1.4;
+}
+
+.hero__visual {
+  position: relative;
+  border-radius: var(--radius-2);
+  overflow: hidden;
+  border: 1px solid color-mix(in oklch, var(--line), transparent 20%);
+  box-shadow: var(--shadow);
+  min-height: 420px;
+  background: linear-gradient(140deg, oklch(24% 0.05 25), var(--bg-1) 55%, var(--bg-0));
+}
+
+.hero__visual::after {
+  content: "";
+  position: absolute;
+  inset: 0;
+  background: radial-gradient(800px 500px at 35% 25%, color-mix(in oklch, var(--red), transparent 55%), transparent 60%),
+    radial-gradient(700px 450px at 80% 65%, color-mix(in oklch, var(--red), transparent 70%), transparent 60%);
+  opacity: 0.9;
+}
+
+.hero__visual .visual__label {
+  position: absolute;
+  left: 18px;
+  bottom: 18px;
+  z-index: 1;
+  display: inline-flex;
+  gap: 10px;
+  align-items: center;
+  padding: 10px 12px;
+  border-radius: var(--radius-pill);
+  background: color-mix(in oklch, var(--bg-0), transparent 20%);
+  border: 1px solid color-mix(in oklch, var(--line), transparent 25%);
+  color: var(--text-0);
+  backdrop-filter: blur(10px);
+}
+
+.pill {
+  font-size: 12px;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+}
+
+.pill--hot {
+  color: var(--text-0);
+  background: color-mix(in oklch, var(--red), black 55%);
+  border: 1px solid color-mix(in oklch, var(--red), white 14%);
+  padding: 6px 10px;
+  border-radius: var(--radius-pill);
+}
+
+/* Sections */
+.section {
+  padding: var(--space-8) 0;
+}
+
+.section--tight { padding: var(--space-7) 0; }
+
+.section__head {
+  display: flex;
+  align-items: flex-end;
+  justify-content: space-between;
+  gap: var(--space-4);
+  margin-bottom: var(--space-6);
+}
+
+.section__head h2 {
+  margin: 0;
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.08em;
+  font-size: clamp(24px, 2.6vw, 40px);
+  line-height: 1.05;
+}
+
+.section__head p {
+  margin: 0;
+  color: var(--text-2);
+  max-width: 64ch;
+  line-height: 1.6;
+}
+
+.card {
+  border-radius: var(--radius-2);
+  border: 1px solid color-mix(in oklch, var(--line), transparent 20%);
+  background: linear-gradient(180deg, color-mix(in oklch, var(--bg-2), transparent 12%), transparent);
+  box-shadow: var(--shadow-soft);
+}
+
+.grid-2 {
+  display: grid;
+  grid-template-columns: repeat(2, 1fr);
+  gap: var(--space-5);
+}
+
+.grid-3 {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: var(--space-4);
+}
+
+.muted { color: var(--text-2); }
+
+.tag {
+  display: inline-flex;
+  align-items: center;
+  gap: 10px;
+  padding: 10px 12px;
+  border-radius: var(--radius-pill);
+  border: 1px solid color-mix(in oklch, var(--line), transparent 30%);
+  color: var(--text-1);
+  background: color-mix(in oklch, var(--bg-2), transparent 26%);
+  font-size: 12px;
+  text-transform: uppercase;
+  letter-spacing: 0.12em;
+}
+
+.tag i {
+  width: 10px;
+  height: 10px;
+  border-radius: 3px;
+  background: var(--red);
+  display: inline-block;
+}
+
+/* Two ways */
+.way {
+  padding: var(--space-5);
+  position: relative;
+  overflow: hidden;
+}
+
+.way::before {
+  content: "";
+  position: absolute;
+  inset: -1px;
+  background: radial-gradient(520px 260px at 20% 0%, color-mix(in oklch, var(--red), transparent 75%), transparent 60%);
+  opacity: 0.9;
+  pointer-events: none;
+}
+
+.way h3 {
+  position: relative;
+  margin: 0 0 var(--space-3);
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.1em;
+  font-size: 22px;
+}
+
+.way p {
+  position: relative;
+  margin: 0 0 var(--space-4);
+  color: var(--text-1);
+  line-height: 1.65;
+}
+
+.way__footer {
+  position: relative;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: var(--space-3);
+}
+
+/* Studio banner */
+.banner {
+  position: relative;
+  overflow: hidden;
+  border-radius: var(--radius-2);
+  border: 1px solid color-mix(in oklch, var(--line), transparent 22%);
+  background: linear-gradient(135deg, color-mix(in oklch, var(--red), black 55%), var(--bg-1) 65%);
+}
+
+.banner::after {
+  content: "";
+  position: absolute;
+  inset: 0;
+  background: radial-gradient(1000px 540px at 25% 25%, color-mix(in oklch, var(--glow), transparent 35%), transparent 60%);
+  opacity: 0.55;
+  pointer-events: none;
+}
+
+.banner__inner {
+  position: relative;
+  padding: var(--space-7);
+  display: grid;
+  grid-template-columns: 1.3fr 0.7fr;
+  gap: var(--space-6);
+  align-items: center;
+}
+
+.banner h3 {
+  margin: 0 0 var(--space-3);
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.08em;
+  font-size: clamp(22px, 2.6vw, 36px);
+  line-height: 1.05;
+}
+
+.banner p {
+  margin: 0;
+  color: var(--text-1);
+  line-height: 1.7;
+}
+
+.banner__cta {
+  display: flex;
+  justify-content: flex-end;
+}
+
+/* Dominant CTA */
+.cta-hero {
+  border-radius: var(--radius-2);
+  border: 1px solid color-mix(in oklch, var(--red), white 12%);
+  background: linear-gradient(180deg, color-mix(in oklch, var(--red), black 35%), color-mix(in oklch, var(--bg-0), var(--red) 30%));
+  box-shadow: 0 26px 80px rgba(230, 57, 70, 0.22);
+  overflow: hidden;
+  position: relative;
+}
+
+.cta-hero::before {
+  content: "";
+  position: absolute;
+  inset: 0;
+  background: radial-gradient(900px 460px at 20% 0%, color-mix(in oklch, var(--glow), transparent 40%), transparent 60%);
+  opacity: 0.85;
+  pointer-events: none;
+}
+
+.cta-hero__inner {
+  position: relative;
+  padding: var(--space-7);
+  display: grid;
+  grid-template-columns: 1.2fr 0.8fr;
+  gap: var(--space-6);
+  align-items: center;
+}
+
+.cta-hero h3 {
+  margin: 0 0 var(--space-2);
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.08em;
+  font-size: clamp(24px, 3vw, 44px);
+  line-height: 1;
+}
+
+.cta-hero p {
+  margin: 0;
+  color: var(--text-0);
+  opacity: 0.92;
+  line-height: 1.65;
+}
+
+.cta-hero__actions {
+  display: grid;
+  gap: 12px;
+  justify-items: end;
+}
+
+/* Carousel */
+.carousel {
+  display: grid;
+  grid-template-columns: 1fr;
+  gap: var(--space-4);
+}
+
+.carousel__frame {
+  position: relative;
+  border-radius: var(--radius-2);
+  overflow: hidden;
+  border: 1px solid color-mix(in oklch, var(--line), transparent 18%);
+  background: var(--bg-1);
+}
+
+.carousel__track {
+  display: flex;
+  will-change: transform;
+  transition: transform var(--dur-3) var(--easing);
+}
+
+.slide {
+  min-width: 100%;
+  aspect-ratio: 16 / 9;
+  position: relative;
+  background: linear-gradient(135deg, oklch(22% 0.05 25), var(--bg-2));
+}
+
+.slide::after {
+  content: "";
+  position: absolute;
+  inset: 0;
+  background: radial-gradient(700px 360px at 20% 20%, color-mix(in oklch, var(--glow), transparent 40%), transparent 60%),
+    radial-gradient(620px 340px at 80% 70%, color-mix(in oklch, var(--red), transparent 65%), transparent 60%);
+  opacity: 0.9;
+}
+
+.slide__content {
+  position: absolute;
+  inset: 0;
+  display: grid;
+  align-content: end;
+  padding: var(--space-6);
+  z-index: 1;
+}
+
+.slide__content strong {
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.12em;
+  font-size: 14px;
+}
+
+.slide__content h3 {
+  margin: var(--space-2) 0 0;
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.08em;
+  font-size: clamp(22px, 2.4vw, 40px);
+  line-height: 1.05;
+}
+
+.carousel__controls {
+  display: flex;
+  gap: 12px;
+  justify-content: space-between;
+  align-items: center;
+}
+
+.carousel__buttons {
+  display: inline-flex;
+  gap: 10px;
+}
+
+.icon-btn {
+  width: 44px;
+  height: 44px;
+  border-radius: 14px;
+  border: 1px solid color-mix(in oklch, var(--line), transparent 18%);
+  background: color-mix(in oklch, var(--bg-2), transparent 18%);
+  color: var(--text-0);
+  cursor: pointer;
+  transition: transform var(--dur-1) var(--easing), border-color var(--dur-1) var(--easing);
+}
+
+.icon-btn:hover {
+  transform: translateY(-1px);
+  border-color: color-mix(in oklch, var(--red), white 12%);
+}
+
+.dots {
+  display: inline-flex;
+  gap: 8px;
+  align-items: center;
+}
+
+.dot {
+  width: 10px;
+  height: 10px;
+  border-radius: 999px;
+  background: color-mix(in oklch, var(--line), transparent 15%);
+  border: 1px solid color-mix(in oklch, var(--line), transparent 10%);
+}
+
+.dot[aria-current="true"] {
+  background: var(--red);
+  border-color: color-mix(in oklch, var(--red), white 15%);
+  box-shadow: 0 0 0 6px color-mix(in oklch, var(--red), transparent 82%);
+}
+
+/* Workout toggle */
+.toggle {
+  display: inline-flex;
+  padding: 6px;
+  border-radius: var(--radius-pill);
+  border: 1px solid color-mix(in oklch, var(--line), transparent 20%);
+  background: color-mix(in oklch, var(--bg-2), transparent 18%);
+  gap: 6px;
+}
+
+.toggle button {
+  border: 0;
+  background: transparent;
+  color: var(--text-1);
+  cursor: pointer;
+  padding: 10px 14px;
+  border-radius: var(--radius-pill);
+  font-weight: 700;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+  font-size: 12px;
+  transition: background var(--dur-2) var(--easing), color var(--dur-2) var(--easing);
+}
+
+.toggle button[aria-pressed="true"] {
+  color: var(--text-0);
