+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.12em;
+  font-size: 14px;
+}
+
+.stat span {
+  display: block;
+  margin-top: 6px;
+  color: var(--text-2);
+  font-size: 13px;
+  line-height: 1.4;
+}
+
+.hero__visual {
+  position: relative;
+  border-radius: var(--radius-2);
+  overflow: hidden;
+  border: 1px solid color-mix(in oklch, var(--line), transparent 20%);
+  box-shadow: var(--shadow);
+  min-height: 420px;
+  background: linear-gradient(140deg, oklch(24% 0.05 25), var(--bg-1) 55%, var(--bg-0));
+}
+
+.hero__visual::after {
+  content: "";
+  position: absolute;
+  inset: 0;
+  background: radial-gradient(800px 500px at 35% 25%, color-mix(in oklch, var(--red), transparent 55%), transparent 60%),
+    radial-gradient(700px 450px at 80% 65%, color-mix(in oklch, var(--red), transparent 70%), transparent 60%);
+  opacity: 0.9;
+}
+
+.hero__visual .visual__label {
+  position: absolute;
+  left: 18px;
+  bottom: 18px;
+  z-index: 1;
+  display: inline-flex;
+  gap: 10px;
+  align-items: center;
+  padding: 10px 12px;
+  border-radius: var(--radius-pill);
+  background: color-mix(in oklch, var(--bg-0), transparent 20%);
+  border: 1px solid color-mix(in oklch, var(--line), transparent 25%);
+  color: var(--text-0);
+  backdrop-filter: blur(10px);
+}
+
+.pill {
+  font-size: 12px;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+}
+
+.pill--hot {
+  color: var(--text-0);
+  background: color-mix(in oklch, var(--red), black 55%);
+  border: 1px solid color-mix(in oklch, var(--red), white 14%);
+  padding: 6px 10px;
+  border-radius: var(--radius-pill);
+}
+
+/* Sections */
+.section {
+  padding: var(--space-8) 0;
+}
+
+.section--tight { padding: var(--space-7) 0; }
+
+.section__head {
+  display: flex;
+  align-items: flex-end;
+  justify-content: space-between;
+  gap: var(--space-4);
+  margin-bottom: var(--space-6);
+}
+
+.section__head h2 {
+  margin: 0;
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.08em;
+  font-size: clamp(24px, 2.6vw, 40px);
+  line-height: 1.05;
+}
+
+.section__head p {
+  margin: 0;
+  color: var(--text-2);
+  max-width: 64ch;
+  line-height: 1.6;
+}
+
+.card {
+  border-radius: var(--radius-2);
+  border: 1px solid color-mix(in oklch, var(--line), transparent 20%);
+  background: linear-gradient(180deg, color-mix(in oklch, var(--bg-2), transparent 12%), transparent);
+  box-shadow: var(--shadow-soft);
+}
+
+.grid-2 {
+  display: grid;
+  grid-template-columns: repeat(2, 1fr);
+  gap: var(--space-5);
+}
+
+.grid-3 {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: var(--space-4);
+}
+
+.muted { color: var(--text-2); }
+
+.tag {
+  display: inline-flex;
+  align-items: center;
+  gap: 10px;
+  padding: 10px 12px;
+  border-radius: var(--radius-pill);
+  border: 1px solid color-mix(in oklch, var(--line), transparent 30%);
+  color: var(--text-1);
+  background: color-mix(in oklch, var(--bg-2), transparent 26%);
+  font-size: 12px;
+  text-transform: uppercase;
+  letter-spacing: 0.12em;
+}
+
+.tag i {
+  width: 10px;
+  height: 10px;
+  border-radius: 3px;
+  background: var(--red);
+  display: inline-block;
+}
+
+/* Two ways */
+.way {
+  padding: var(--space-5);
+  position: relative;
+  overflow: hidden;
+}
+
+.way::before {
+  content: "";
+  position: absolute;
+  inset: -1px;
+  background: radial-gradient(520px 260px at 20% 0%, color-mix(in oklch, var(--red), transparent 75%), transparent 60%);
+  opacity: 0.9;
+  pointer-events: none;
+}
+
+.way h3 {
+  position: relative;
+  margin: 0 0 var(--space-3);
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.1em;
+  font-size: 22px;
+}
+
+.way p {
+  position: relative;
+  margin: 0 0 var(--space-4);
+  color: var(--text-1);
+  line-height: 1.65;
+}
+
+.way__footer {
+  position: relative;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: var(--space-3);
+}
+
+/* Studio banner */
+.banner {
+  position: relative;
+  overflow: hidden;
+  border-radius: var(--radius-2);
+  border: 1px solid color-mix(in oklch, var(--line), transparent 22%);
+  background: linear-gradient(135deg, color-mix(in oklch, var(--red), black 55%), var(--bg-1) 65%);
+}
+
+.banner::after {
+  content: "";
+  position: absolute;
+  inset: 0;
+  background: radial-gradient(1000px 540px at 25% 25%, color-mix(in oklch, var(--glow), transparent 35%), transparent 60%);
+  opacity: 0.55;
+  pointer-events: none;
+}
+
+.banner__inner {
+  position: relative;
+  padding: var(--space-7);
+  display: grid;
+  grid-template-columns: 1.3fr 0.7fr;
+  gap: var(--space-6);
+  align-items: center;
+}
+
+.banner h3 {
+  margin: 0 0 var(--space-3);
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.08em;
+  font-size: clamp(22px, 2.6vw, 36px);
+  line-height: 1.05;
+}
+
+.banner p {
+  margin: 0;
+  color: var(--text-1);
+  line-height: 1.7;
+}
+
+.banner__cta {
+  display: flex;
+  justify-content: flex-end;
+}
+
+/* Dominant CTA */
+.cta-hero {
+  border-radius: var(--radius-2);
+  border: 1px solid color-mix(in oklch, var(--red), white 12%);
+  background: linear-gradient(180deg, color-mix(in oklch, var(--red), black 35%), color-mix(in oklch, var(--bg-0), var(--red) 30%));
+  box-shadow: 0 26px 80px rgba(230, 57, 70, 0.22);
+  overflow: hidden;
+  position: relative;
+}
+
+.cta-hero::before {
+  content: "";
+  position: absolute;
+  inset: 0;
+  background: radial-gradient(900px 460px at 20% 0%, color-mix(in oklch, var(--glow), transparent 40%), transparent 60%);
+  opacity: 0.85;
+  pointer-events: none;
+}
+
+.cta-hero__inner {
+  position: relative;
+  padding: var(--space-7);
+  display: grid;
+  grid-template-columns: 1.2fr 0.8fr;
+  gap: var(--space-6);
+  align-items: center;
+}
+
+.cta-hero h3 {
+  margin: 0 0 var(--space-2);
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.08em;
+  font-size: clamp(24px, 3vw, 44px);
+  line-height: 1;
+}
+
+.cta-hero p {
+  margin: 0;
+  color: var(--text-0);
+  opacity: 0.92;
+  line-height: 1.65;
+}
+
+.cta-hero__actions {
+  display: grid;
+  gap: 12px;
+  justify-items: end;
+}
+
+/* Carousel */
+.carousel {
+  display: grid;
+  grid-template-columns: 1fr;
+  gap: var(--space-4);
+}
+
+.carousel__frame {
+  position: relative;
+  border-radius: var(--radius-2);
+  overflow: hidden;
+  border: 1px solid color-mix(in oklch, var(--line), transparent 18%);
+  background: var(--bg-1);
+}
+
+.carousel__track {
+  display: flex;
+  will-change: transform;
+  transition: transform var(--dur-3) var(--easing);
+}
+
+.slide {
+  min-width: 100%;
+  aspect-ratio: 16 / 9;
+  position: relative;
+  background: linear-gradient(135deg, oklch(22% 0.05 25), var(--bg-2));
+}
+
+.slide::after {
+  content: "";
+  position: absolute;
+  inset: 0;
+  background: radial-gradient(700px 360px at 20% 20%, color-mix(in oklch, var(--glow), transparent 40%), transparent 60%),
+    radial-gradient(620px 340px at 80% 70%, color-mix(in oklch, var(--red), transparent 65%), transparent 60%);
+  opacity: 0.9;
+}
+
+.slide__content {
+  position: absolute;
+  inset: 0;
+  display: grid;
+  align-content: end;
+  padding: var(--space-6);
+  z-index: 1;
+}
+
+.slide__content strong {
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.12em;
+  font-size: 14px;
+}
+
+.slide__content h3 {
+  margin: var(--space-2) 0 0;
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.08em;
+  font-size: clamp(22px, 2.4vw, 40px);
+  line-height: 1.05;
+}
+
+.carousel__controls {
+  display: flex;
+  gap: 12px;
+  justify-content: space-between;
+  align-items: center;
+}
+
+.carousel__buttons {
+  display: inline-flex;
+  gap: 10px;
+}
+
+.icon-btn {
+  width: 44px;
+  height: 44px;
+  border-radius: 14px;
+  border: 1px solid color-mix(in oklch, var(--line), transparent 18%);
+  background: color-mix(in oklch, var(--bg-2), transparent 18%);
+  color: var(--text-0);
+  cursor: pointer;
+  transition: transform var(--dur-1) var(--easing), border-color var(--dur-1) var(--easing);
+}
+
+.icon-btn:hover {
+  transform: translateY(-1px);
+  border-color: color-mix(in oklch, var(--red), white 12%);
+}
+
+.dots {
+  display: inline-flex;
+  gap: 8px;
+  align-items: center;
+}
+
+.dot {
+  width: 10px;
+  height: 10px;
+  border-radius: 999px;
+  background: color-mix(in oklch, var(--line), transparent 15%);
+  border: 1px solid color-mix(in oklch, var(--line), transparent 10%);
+}
+
+.dot[aria-current="true"] {
+  background: var(--red);
+  border-color: color-mix(in oklch, var(--red), white 15%);
+  box-shadow: 0 0 0 6px color-mix(in oklch, var(--red), transparent 82%);
+}
+
+/* Workout toggle */
+.toggle {
+  display: inline-flex;
+  padding: 6px;
+  border-radius: var(--radius-pill);
+  border: 1px solid color-mix(in oklch, var(--line), transparent 20%);
+  background: color-mix(in oklch, var(--bg-2), transparent 18%);
+  gap: 6px;
+}
+
+.toggle button {
+  border: 0;
+  background: transparent;
+  color: var(--text-1);
+  cursor: pointer;
+  padding: 10px 14px;
+  border-radius: var(--radius-pill);
+  font-weight: 700;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+  font-size: 12px;
+  transition: background var(--dur-2) var(--easing), color var(--dur-2) var(--easing);
+}
+
+.toggle button[aria-pressed="true"] {
+  color: var(--text-0);
+  background: color-mix(in oklch, var(--red), black 55%);
+  box-shadow: 0 12px 30px rgba(230, 57, 70, 0.2);
+}
+
+.switcher {
+  margin-top: var(--space-4);
+  display: grid;
+  grid-template-columns: 1fr;
+  gap: var(--space-4);
+}
+
+.switcher__panel {
+  padding: var(--space-5);
+}
+
+.switcher__panel h3 {
+  margin: 0 0 var(--space-2);
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.1em;
+}
+
+.switcher__panel p {
+  margin: 0;
+  color: var(--text-1);
+  line-height: 1.7;
+}
+
+.fade {
+  animation: fadeIn var(--dur-2) var(--easing);
+}
+
+@keyframes fadeIn {
+  from { opacity: 0; transform: translateY(6px); }
+  to { opacity: 1; transform: translateY(0px); }
+}
+
+/* Table */
+.table {
+  width: 100%;
+  border-collapse: collapse;
+  overflow: hidden;
+  border-radius: var(--radius-2);
+  border: 1px solid color-mix(in oklch, var(--line), transparent 20%);
+  background: color-mix(in oklch, var(--bg-2), transparent 14%);
+}
+
+.table th,
+.table td {
+  text-align: left;
+  padding: 14px 16px;
+  border-bottom: 1px solid color-mix(in oklch, var(--line), transparent 15%);
+}
+
+.table th {
+  font-size: 12px;
+  letter-spacing: 0.14em;
+  text-transform: uppercase;
+  color: var(--text-2);
+  background: color-mix(in oklch, var(--bg-1), transparent 25%);
+}
+
+.table tr:hover td {
+  background: color-mix(in oklch, var(--bg-1), transparent 35%);
+}
+
+/* Instructors */
+.filters {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: center;
+  justify-content: space-between;
+  gap: var(--space-4);
+  padding: var(--space-4);
+}
+
+.filters label {
+  font-size: 12px;
+  letter-spacing: 0.14em;
+  text-transform: uppercase;
+  color: var(--text-2);
+}
+
+.select {
+  min-width: 240px;
+  padding: 12px 14px;
+  border-radius: 14px;
+  background: color-mix(in oklch, var(--bg-2), transparent 18%);
+  border: 1px solid color-mix(in oklch, var(--line), transparent 18%);
+  color: var(--text-0);
+}
+
+.grid-cards {
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: var(--space-4);
+}
+
+.card-person {
+  overflow: hidden;
+  position: relative;
+}
+
+.card-person__photo {
+  height: 160px;
+  background: linear-gradient(135deg, color-mix(in oklch, var(--red), black 50%), var(--bg-2));
+  position: relative;
+}
+
+.card-person__photo::after {
+  content: "";
+  position: absolute;
+  inset: 0;
+  background: radial-gradient(420px 220px at 20% 20%, color-mix(in oklch, var(--glow), transparent 35%), transparent 60%);
+  opacity: 0.85;
+}
+
+.card-person__body {
+  padding: var(--space-4);
+  display: grid;
+  gap: 10px;
+}
+
+.card-person__name {
+  margin: 0;
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.1em;
+  font-size: 18px;
+}
+
+.card-person__meta {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 10px;
+  color: var(--text-2);
+  font-size: 13px;
+}
+
+.chip {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  padding: 8px 10px;
+  border-radius: var(--radius-pill);
+  border: 1px solid color-mix(in oklch, var(--line), transparent 16%);
+  background: color-mix(in oklch, var(--bg-2), transparent 24%);
+  font-size: 12px;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+}
+
+.chip i {
+  width: 8px;
+  height: 8px;
+  border-radius: 3px;
+  background: var(--red);
+  display: inline-block;
+}
+
+/* FAQ */
+.accordion {
+  display: grid;
+  gap: 12px;
+}
+
+.acc-item {
+  border-radius: var(--radius-2);
+  border: 1px solid color-mix(in oklch, var(--line), transparent 20%);
+  overflow: hidden;
+  background: color-mix(in oklch, var(--bg-2), transparent 18%);
+}
+
+.acc-btn {
+  width: 100%;
+  text-align: left;
+  padding: 18px 18px;
+  border: 0;
+  background: transparent;
+  color: var(--text-0);
+  cursor: pointer;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 14px;
+}
+
+.acc-btn strong {
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.08em;
+  font-size: 16px;
+}
+
+.acc-icon {
+  width: 34px;
+  height: 34px;
+  border-radius: 12px;
+  border: 1px solid color-mix(in oklch, var(--line), transparent 18%);
+  background: color-mix(in oklch, var(--bg-1), transparent 18%);
+  display: grid;
+  place-items: center;
+  flex: 0 0 auto;
+}
+
+.acc-panel {
+  padding: 0 18px 18px;
+  color: var(--text-1);
+  line-height: 1.7;
+  display: none;
+}
+
+.acc-item[open] .acc-panel { display: block; }
+
+/* Newsletter */
+.newsletter {
+  display: grid;
+  grid-template-columns: 1.1fr 0.9fr;
+  gap: var(--space-6);
+  padding: var(--space-6);
+}
+
+.newsletter h3 {
+  margin: 0 0 var(--space-2);
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.08em;
+  font-size: 28px;
+}
+
+.newsletter p { margin: 0; color: var(--text-2); line-height: 1.7; }
+
+.form {
+  display: grid;
+  gap: 10px;
+}
+
+.field {
+  display: grid;
+  gap: 8px;
+}
+
+.field label {
+  font-size: 12px;
+  letter-spacing: 0.14em;
+  text-transform: uppercase;
+  color: var(--text-2);
+}
+
+.input {
+  width: 100%;
+  padding: 14px 14px;
+  border-radius: 14px;
+  border: 1px solid color-mix(in oklch, var(--line), transparent 18%);
+  background: color-mix(in oklch, var(--bg-2), transparent 18%);
+  color: var(--text-0);
+}
+
+.help {
+  font-size: 13px;
+  color: var(--text-2);
+  line-height: 1.5;
+}
+
+.help--ok { color: color-mix(in oklch, var(--success), white 10%); }
+.help--err { color: color-mix(in oklch, var(--danger), white 10%); }
+
+/* Footer */
+footer {
+  padding: var(--space-7) 0;
+  border-top: 1px solid color-mix(in oklch, var(--line), transparent 25%);
+  background: linear-gradient(180deg, transparent, color-mix(in oklch, var(--bg-0), black 20%));
+}
+
+.footer__grid {
+  display: grid;
+  grid-template-columns: 1.2fr repeat(3, 1fr);
+  gap: var(--space-6);
+}
+
+.footer__col h4 {
+  margin: 0 0 12px;
+  font-size: 12px;
+  letter-spacing: 0.14em;
+  text-transform: uppercase;
+  color: var(--text-2);
+}
+
+.footer__col a {
+  display: block;
+  padding: 8px 0;
+  color: var(--text-1);
+}
+
+.footer__col a:hover { color: var(--text-0); }
+
+.footer__bottom {
+  margin-top: var(--space-6);
+  display: flex;
+  flex-wrap: wrap;
+  gap: 12px;
+  justify-content: space-between;
+  align-items: center;
+  color: var(--text-2);
+  font-size: 13px;
+}
+
+.country {
+  position: relative;
+}
+
+.country button {
+  display: inline-flex;
+  align-items: center;
+  gap: 10px;
+}
+
+.country-menu {
+  position: absolute;
+  right: 0;
+  bottom: calc(100% + 10px);
+  min-width: 220px;
+  border-radius: 16px;
+  border: 1px solid color-mix(in oklch, var(--line), transparent 18%);
+  background: color-mix(in oklch, var(--bg-1), transparent 6%);
+  box-shadow: var(--shadow);
+  display: none;
+  padding: 8px;
+}
+
+.country-menu[aria-hidden="false"] { display: block; }
+
+.country-menu button {
+  width: 100%;
+  text-align: left;
+  border: 0;
+  background: transparent;
+  color: var(--text-0);
+  padding: 10px 12px;
+  border-radius: 12px;
+  cursor: pointer;
+}
+
+.country-menu button:hover {
+  background: color-mix(in oklch, var(--bg-2), transparent 22%);
+}
+
+/* Page utility */
+.page-head {
+  padding: var(--space-7) 0 var(--space-6);
+}
+
+.page-head h1 {
+  margin: 0 0 var(--space-2);
+  font-family: Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.08em;
+  font-size: clamp(34px, 3.6vw, 56px);
+  line-height: 0.95;
+}
+
+.page-head p { margin: 0; color: var(--text-1); max-width: 70ch; line-height: 1.7; }
+
+/* Responsive */
+@media (max-width: 1024px) {
+  .hero__grid { grid-template-columns: 1fr; }
+  .banner__inner, .cta-hero__inner { grid-template-columns: 1fr; }
+  .banner__cta { justify-content: flex-start; }
+  .cta-hero__actions { justify-items: start; }
+  .grid-cards { grid-template-columns: repeat(2, 1fr); }
+}
+
+@media (max-width: 860px) {
+  header.site-header { top: 41px; }
+  .nav__links { display: none; }
+  .hamburger { display: inline-grid; place-items: center; }
+  .mobile-drawer {
+    display: none;
