const fs=require('fs');
const files=['index.html','the-workout.html','instructors.html','ride-faq.html','digital-platform.html']
  .map(f=>'output/'+f);
for (const f of files){
  const html=fs.readFileSync(f,'utf8');
  // basic: ensure no absolute links to /app/output
  if (/\/app\/output/.test(html)) throw new Error('Found absolute path in '+f);
  // ensure nav links are relative (rough check)
  if (!html.includes('href="the-workout.html"')) throw new Error('Missing workout link in '+f);
  if (!html.includes('href="instructors.html"')) throw new Error('Missing instructors link in '+f);
  if (!html.includes('href="ride-faq.html"')) throw new Error('Missing ride link in '+f);
  if (!html.includes('href="digital-platform.html"')) throw new Error('Missing digital link in '+f);
}
console.log('nav ok');
